import{_ as a,a as t,b as _}from"./chunks/fixpipe_buffer.Dfr8Gfsw.js";import{_ as r,o,a as i,b as c}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵计算的搬出","link":"/api/SIMD-API/c_api/cube_datamove/cube_compute_store/cube_compute_store"},{"text":"矩阵搬出总体说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_compute_store/cube_compute_store_overall_description"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_store/cube_compute_store_overall_description.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_compute_store/cube_compute_store_overall_description.md","lastUpdated":1791622466000}'),p={name:"api/SIMD-API/c_api/cube_datamove/cube_compute_store/cube_compute_store_overall_description.md"};function s(u,e,n,l,m,d){return o(),i("div",null,[...e[0]||(e[0]=[c('<div><article class="markdown-body"><h1>矩阵搬出总体说明</h1><p>矩阵计算的搬出是Ascend C编程框架中用于数据搬运的一类核心接口，主要实现从L0C Buffer到Global Memory和L1 Buffer的数据传输。该接口系列提供了多种数据搬运模式，能够满足矩阵计算中的数据搬运需求，通常在asc_mmad接口后配合使用。</p><p>矩阵计算的搬出接口支持多种随路搬运场景，包括<strong>随路量化、随路ReLU、随路格式转换（Nz2ND、Nz2DN）、随路通道拆分（Channel Split）、随路通道合并（Channel Merge）</strong>。通过配置接口参数与辅助寄存器，开发者可以精确控制数据的搬运路径、起始位置、搬运长度、随路搬运能力等关键信息，充分利用硬件的数据搬运能力，最大化算子的整体执行性能。</p><div data-filter="950,A3,910b"><p>矩阵计算的搬出整体流程如下图所示：</p></div><div data-filter="A3,910b"><p><strong>图1</strong> 矩阵计算的搬出整体流程图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><p><img src="'+a+'" alt></p></div><div data-filter="950"><p><strong>图2</strong> 矩阵计算的搬出整体流程图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><p><img src="'+t+'" alt></p></div><p>其中，Fixpipe Buffer不同的量化模式对应的内存排布如下：</p><p><strong>图3</strong> Fixpipe Buffer内存排布图</p><p><img src="'+_+'" alt></p><p>搬出接口及架构版本见<a href="asc_copy_l0c2gm.html">L0C到GM</a>和<a href="asc_copy_l0c2l1.html">L0C到L1</a>。输出布局参见<a href="../cube_store_key_features/NZ2NZ.html">NZ2NZ</a>及<a href="../cube_store_key_features/NZ2ND.html">NZ2ND</a>；数值处理参见<a href="../cube_store_key_features/accompanying_quantization.html">随路量化</a>、<a href="../cube_store_key_features/accompanying_relu.html">随路ReLU</a>及<a href="../cube_store_key_features/accompanying_quantization_and_relu_scenario_combination.html">场景组合</a>。量化/激活参数搬入见<a href="../cube_compute_load/asc_copy_l12fb.html">asc_copy_l12fb</a>，配套寄存器配置见<a href="../cube_store_aux_config/cube_store_aux_config.html">矩阵搬出辅助配置接口</a>。</p><div data-filter="950"><p>Ascend 950PR&amp;950DT系列产品还支持<a href="asc_copy_l0c2ub.html">L0C到UB</a>搬出；L0C到GM的输出布局还可选择<a href="../cube_store_key_features/NZ2DN.html">NZ2DN</a>。</p></div></article></div>',1)])])}const g=r(p,[["render",s]]);export{h as __pageData,g as default};
